insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4af1893d-9998-48eb-b854-d76a961d685a', 'ja', '距離の変化は、なぜ急ではなく、少しずつであるべきなのですか？', '["急な動きは踏み込まれたように感じられ、打ち解けた空気を壊すから", "少しずつの変化は、高まっていく気持ちのトーンに合うから", "すばやく近づくことは、いつでも強い関心を伝えるから"]'::jsonb, 'ゆっくり進めることで、安心感と、相手に合わせる余地が保たれます。')
