insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('645db147-5379-46df-8e63-f2d46db760eb', 'ja', '会話の中で、彼女が温かく笑い、身を寄せてきます。次に何ができますか？', '["安全のために、手をポケットに入れたままにする", "ほほえみながら、前腕に短く軽く触れる", "距離を縮めるために、すぐにハグをする", "導くように、腰に手を当てる"]'::jsonb, '彼女がしっかり会話に乗っているときの短く軽いタッチは、相性の良さを自然に強めます。')
