insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('69e57da2-5fe8-46fa-b9e1-c7e7f7579196', 'ja', '駆け引きの中で、距離を調整する一番の目的は何ですか？', '["支配力を示すこと", "できるだけ早く、惹かれる気持ちを高めること", "彼女の境界線を試すこと", "体の距離を、気持ちの上での心地よさに合わせること"]'::jsonb, '距離の近さがうまくいくのは、気持ちの上での心地よさを映しているときです。限界を押したり、試したりするときではありません。')
