insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('6a0ee7f4-bdfd-47a6-901c-adfd7c6f56fa', 'ja', '彼女は会話の中で、さらりと冗談を言います。合う褒め言葉は、どれですか？', '["「最高に面白いですね。お笑いをやったほうがいいですよ」", "「女の子にしては、面白いですね」", "「そのユーモアのセンス、好きです。すごく個性的で」"]'::jsonb, '一番良い返しは、その場を盛り上げようとするのではなく、その場の気楽さを映すものです。')
