insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('731d74c4-4ac6-43b0-bdcf-69cb8db3d00d', 'ja', '彼女が「私、ここに来すぎかもしれません」と言います。次に何と言えますか？', '["「もう、名前のついたドリンクをつくってもらっていいくらいですね」", "「いいお店ですよね」", "「そんなことはありえませんよ」", "「どれくらい来るんですか？」"]'::jsonb, '温かさのある、遊び心を込めた大げさな言い方は、その瞬間を記憶に残るものにします。')
