insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('76d8660f-5734-4d14-9168-b2bd84bfeedf', 'ja', '褒め言葉を伝えるのに、一番良いタイミングはいつですか？', '["最初のひと言として", "LINEを聞く直前に", "彼女が何かを表現したあと、自然に", "彼女が先に褒めてくれたときだけ"]'::jsonb, '褒め言葉は、やり取りの中から自然に出てきたとき、一番よく届きます。')
