insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('78f2a3a1-b8f1-4d88-9854-152a0b2895ec', 'ja', '彼女が、ボードゲームではかなり負けず嫌いだと話します。面白い返しは、どれですか？', '["「競争は、体に良くないこともありますよ」", "「こちらは、勝つことにとても真剣です」", "「こちらが勝っても、テーブルをひっくり返さないでくださいね」", "「ボードゲームは楽しいですよね」"]'::jsonb, '軽い大げさな言い方は、遊び心のある雰囲気を保ち、やり取りを盛り上げます。')
