insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('79b0dd38-20dd-41fe-91af-1e353ef1dd35', 'ja', '彼女がエピソードを話し終え、期待するようにこちらを見ます。性的な緊張感を生めるのは、どれですか？', '["「いい話ですね」とさっと言って、次の質問をする", "すぐに彼女の知性を褒める", "目をそらして、話題を変える", "少し長く目を合わせ、ゆっくりほほえんで、やわらかく「話し方、すごく上手でしたね」と言う"]'::jsonb, '長めの視線と温かい伝え方は、プレッシャーをかけずに、可能性を持ち込みます。')
