insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('7c711059-22dd-4139-9523-2de1103e125a', 'ja', 'エネルギーをその場に合わせるとは、どういうことですか？', '["いつでも高い興奮を持ち込むこと", "変化をつけずに、そっくり同じにすること", "どこでも同じ雰囲気を保つこと", "今ある気分に合わせるか、少しだけ引き上げること"]'::jsonb, 'まず今あるエネルギーに合わせ、その場が許すなら、少しだけ引き上げましょう。')
