insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9307f2f7-e573-4a52-81e2-e255d0fe0983', 'ja', '3分間の会話が、笑いとともに終わりますが、LINEは交換していません。これをどう捉えるべきですか？', '["うまくいった、楽しい時間", "完全な失敗", "次につなげるチャンスを逃した", "時間の無駄"]'::jsonb, '目指すのは、二人で分かち合う前向きなエネルギーです。その先の結果ではありません。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('94b2a1ba-b2aa-42e8-bf7a-d35951d81430', 'ja', 'バーで、にぎやかなグループに声をかけようとしています。どんなエネルギーがうまくいきますか？', '["相手のにぎやかさと釣り合うように、リラックスした落ち着いたエネルギーを持ち込む", "明るいトーンで、相手のにぎやかなエネルギーに合わせる", "良い意味で目立つように、相手のエネルギーを少し上回る"]'::jsonb, '人は、自分たちのリズムに合った、明るいエネルギーに一番よく応えます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('95247c9b-621b-4050-bfa2-a28902ab1b90', 'ja', '軽い勝負は、なぜふつうの会話よりも速く相性の良さを育てるのですか？', '["小さな緊張感と、気持ちの入り方を生むから", "知らない人同士を、ひとときのライバルやチームメイトに変えるから", "彼女の積極的な参加が必要になるから", "上のすべて"]'::jsonb, '遊びの賭けは、本当のプレッシャーなしに、エネルギーと関わりに火をつけます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a1c414f9-7ab4-4475-a07e-69d6eb6b1ba4', 'ja', '彼女が、チェスが好きだと冗談めかして言います。駆け引きになる返しとして、何と言えますか？', '["「チェスは、すごく難しいですよね」", "「チェスは、ずいぶん簡単な競技ですよね」", "「競争は、体に良くないですよ」", "「クイーンの守り方なら、心得ていますよ」"]'::jsonb, '彼女の遊び心に合わせて、軽い掛け合いとエネルギーを盛り上げましょう。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a25d7cd3-3b21-4ccb-89ba-1cffbbe6a49d', 'ja', '軽い掛け合いは、なぜ恋愛的な相性を育てるのに役立つのですか？', '["気楽な緊張感と遊び心を生むから", "笑いを通じて、気持ちの距離を縮めるから", "会話を、まじめで礼儀正しいままに保つから", "返し合うやり取りのエネルギーを持ち込むから"]'::jsonb, '遊び心が、駆け引きを、ただの感じのいい打ち解けた空気と分けます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a2f4b225-b8a7-4317-8f9e-d5d7ce3e0c73', 'ja', '相手を尊重した気づかいを示す行動は、どれですか？', '["彼女の気を変えさせるために、会話を続けること", "「彼氏がいます」という言葉を、詮索せずに受け入れること", "彼女の返事が短いとき、一歩引くこと", "会話に乗っていないとき、礼儀正しくやり取りを終えること"]'::jsonb, '尊重とは、関心がないときに、どれだけ早く合わせ直し、どれだけすっきり立ち去れるかです。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a621c77a-69b0-4f0a-8e2f-6e12dbf8bc0b', 'ja', '簡単にはなびかない姿勢は、なぜ惹かれる気持ちを生むのですか？', '["彼女の承認を追いかけていることを示すから", "無条件に同意するパターンを破るから", "彼女を持ち上げすぎるのではなく、対等な相手として扱うから"]'::jsonb, '簡単にはなびかない姿勢は、追いかける形を、釣り合いの取れた、お互いに選び合う形へとひっくり返します。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a64d80aa-89d6-4008-bb0c-2e3f3d44e8d8', 'ja', '性的な緊張感の「火花」を生むものは、何ですか？', '["友達以上なのかどうかについての、かすかな不確かさ", "すべてを、先が読めて感じのいいままに保つこと", "早い段階で、恋愛的な意図をはっきり述べること", "体の存在を、いっさい意識しないようにすること"]'::jsonb, '「これは、それ以上の何かなのだろうか」という問いが、注意を引きつけ続けます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
commit;
